This is our issues list. It works but it's ugly and feels slow compared to Linear. I want to hand a design tool a really good prompt to redesign it — but nothing about how it behaves should change.

```tsx
export function IssuesList() {
  const [status, setStatus] = useState('all')
  const { data } = useSWR(`/api/issues?status=${status}`)

  return (
    <div>
      <h2>Issues</h2>
      <select value={status} onChange={(e) => setStatus(e.target.value)}>
        <option value="all">All</option>
        <option value="open">Open</option>
        <option value="closed">Closed</option>
      </select>
      <ul>
        {data?.issues.map((i) => (
          <li key={i.id} onClick={() => router.push(`/issues/${i.id}`)}>
            <strong>{i.title}</strong>
            <span>{i.status}</span>
            <span>{i.assignee?.name ?? 'Unassigned'}</span>
          </li>
        ))}
      </ul>
    </div>
  )
}
```

